	if (PulseManager::Instance().IncreaseClock(GetPlayerID(), MT2009_PLUS_PULSE_CHEST_NOTICE, std::chrono::milliseconds(1000)))
		ChatPacket(CHAT_TYPE_INFO, LC_TEXT("You need room for atleast 3 slot item to open the box."));
